      }

      set header(value) {
        this.shadowRoot.querySelector('#title').textContent = value;
      }

      set message(value) {
        this.shadowRoot.querySelector('#message').innerHTML = value;
      }

      set actionFn(value) {
        this.#actionFn = value;
      }
      set actionName(value) {
